      {
        question: "What does “sensitised skin” actually mean?",
        answer: "Sensitised skin means the barrier has become weakened and inflammation is active. This often leads to burning, stinging, redness, peeling and unpredictable flare-ups. It is a skin behaviour state, not a permanent skin type."
      },
      {
        question: "Why does my skin react to products I used to tolerate?",
        answer: "When the barrier is disrupted, ingredients penetrate too deeply and trigger irritation. This can happen after over-exfoliation, frequent treatments, stress or hormonal change."
      },
      {
        question: "Can sensitised skin still look oily or congested?",
        answer: "Yes. Sensitised skin can still overproduce oil while remaining dehydrated underneath. This creates a confusing combination of breakouts and irritation, which requires careful sequencing."
      },
      {
        question: "How do I know if my skin needs recovery before more treatments?",
        answer: "If your skin stings, burns, peels, flushes easily or feels tight and uncomfortable, it likely needs stabilisation before any corrective treatments."
      },
      {
        question: "Is redness after using acids always a “purge”?",
        answer: "Not always. Purging is temporary and mild, but ongoing redness, burning or peeling is often irritation and barrier damage. At ULANDA, we assess whether your skin is inflamed or simply adjusting."
      },
      {
        question: "Can professional treatments help recovery or should I avoid everything?",
        answer: "Recovery can be supported professionally through barrier-safe treatments such as hydration therapy and LED support. The key is choosing treatments that reduce inflammation rather than stimulating the skin further."
      },
      {
        question: "How long does it take for sensitised skin to settle?",
        answer: "Many clients notice improvement within 2–4 weeks, but full barrier resilience often requires 6–12 weeks depending on severity and lifestyle triggers."
      },
      {
        question: "Can sensitised skin be linked to dehydration and tightness?",
        answer: "Yes. Sensitised skin often loses hydration rapidly due to barrier disruption. Dehydration is one of the earliest signs of recovery fatigue."
      },
      {
        question: "Can post-treatment recovery cause dryness and flaking?",
        answer: "Yes. Dryness and flaking are common in recovery phases, especially after excessive exfoliation or strong actives. This is why structured repair is essential."
      },
      {
        question: "Can sensitised skin lead to dullness and loss of glow?",
        answer: "Yes. When the barrier is inflamed and dehydrated, glow reduces dramatically. Many clients regain radiance once the skin is stabilised and hydrated properly."
      }
